  ["HUNTER_TRACKING_TEXT"] = { "ハンターの追跡", 0xae24c2e4, "." },
  ["HolidayDescription:1"] = { "Darkmoon Faireがやって来ました。今回の開催地はのどかなElwynn Forestです。\r\n\r\nSilas Darkmoonと一座に会い、知恵と度胸を試すゲームで遊び、Azerothの四方から……さらにその彼方から集められた珍しい見世物をご覧ください！", 0xc5ca3498, "." },
  ["HolidayDescription:10"] = { "一年で最も暑い季節に捧げる、歓喜と祝祭の時です。", 0xaa87d20d, "." },
  ["HolidayDescription:11"] = { "日が沈むと、Midsummerの終わりを祝って毎時豪華な花火が打ち上げられます。\r\n\r\nショーを見るには、いずれかの首都かBooty Bayを訪れてください。", 0x81ab5c5b, "." },
  ["HolidayDescription:12"] = { "孤児に英雄の暮らしがどんなものかを見せてあげましょう！StormwindのOrphan Matron NightingaleかOrgrimmarのOrphan Matron Battlewailを訪ね、子どもの夢をかなえてあげてください。", 0x3c539eb5, "." },
  ["HolidayDescription:13"] = { "Smokywood Pasturesの厚意により、Greatfather WinterがIronforgeとOrgrimmarの街を訪れています。そしてAzeroth中が、陽気に過ごす季節を迎えています！", 0xe3e2b174, "." },
  ["HolidayDescription:14"] = { "Noblegardenの祝祭がやって来ました。若き英雄たちが初めて力を試す場所である各種族の修練場には、巧みに隠された宝の卵があります。いくつ見つけられるでしょうか？", 0x96ddb867, "." },
  ["HolidayDescription:15"] = { "Hallow's Endは、ForsakenがScourgeから離反したことを祝う祭りです。\r\n\r\nAzerothの宿屋の主人たちが、頼んだ人には誰にでもお菓子といたずらを振る舞い、楽しさといたずらに満ちた時を迎えます。", 0xf5362762, "." },
  ["HolidayDescription:16"] = { "Harvest Festivalは、友や同盟者を助けるために命を捧げた人々をしのぶ時です。倒れた英雄たちをたたえ、OrgrimmarとIronforgeの外で宴が開かれます。", 0x1ff1f393, "." },
  ["HolidayDescription:17"] = { "毎年、Moongladeのドルイドたちは、古の悪に対する自分たちの街の偉大な勝利を祝う祭りを開きます。Lunar Festivalの間、Azerothの人々は、長老たちの賢い知恵をたたえ、豪華なごちそうを分かち合い、そしてもちろん……花火をたくさん打ち上げることで、長老たちを敬う機会を得られます！", 0x16d5ac80, "." },
  ["HolidayDescription:2"] = { "Azerothは祝賀ムードです！各種族の首都では、一晩中、毎時花火のショーが開かれます！", 0xcf7074ee, "." },
  ["HolidayDescription:22"] = { "Alterac Valleyの戦いが激しさを増しています。主君に剣を捧げてAlteracで戦う者には、より多くの名誉が与えられます。", 0x4849131d, "." },
  ["HolidayDescription:23"] = { "Arathi Basinの戦いが激しさを増しています。主君に剣を捧げてArathiで戦う者には、より多くの名誉が与えられます。", 0x48c2c5d4, "." },
  ["HolidayDescription:25"] = { "Warsong Gulchの戦いが激しさを増しています。主君に剣を捧げてGulchで戦う者には、より多くの名誉が与えられます。", 0x32d254a4, "." },
  ["HolidayDescription:26"] = { "Darkmoon Faireがやって来ました。今回の開催地はThunder Bluffのふもとです。\r\n\r\nSilas Darkmoonと一座に会い、知恵と度胸を試すゲームで遊び、Azerothの四方から……さらにその彼方から集められた珍しい見世物をご覧ください！", 0xf0bd31ce, "." },
  ["HolidayDescription:4"] = { "Stranglethorn Valeの海岸沿いで開かれる釣り大会です。tastyfishをできるだけたくさん釣り上げましょう！\r\n\r\n最初に40匹を釣り上げて大賞を手にする名人の釣り人は、あなたでしょうか？", 0x1e39549d, "." },
  ["HolidayDescription:512"] = { "Darkspear Islandsでの戦いが緊迫しています。参戦して、あなたの力を示しましょう！", 0x602d549d, "." },
  ["HolidayDescription:9"] = { "Azerothの主要都市には何かが漂っています。多くの衛兵や町の人々が、恋に落ちた市民たちと贈り物を贈り合って日々を過ごしています。", 0xc46498f4, "." },
})
